def get_order_query_additional_data(self, included_data):
    additional_data = defaultdict(dict)
    for item in included_data:
        item_id = item["id"]
        item_type = item["type"]
        relationships = item.get("relationships", {})
        attributes = item["attributes"]
        if item_type == "order-channels":
            additional_data["channels"][item_id] = attributes["name"]
        elif item_type == "order-items":
            # this is a result of an archived product
            if (
                not relationships.get("product")
                or not relationships["product"]["data"]
            ):
                continue
            additional_data["order_items"][item_id] = {
                **attributes,
                "product_id": relationships["product"]["data"]["id"],
            }
        elif item_type == "products":
            # expand product kits/components?
            additional_data["products"][item_id] = {
                "sku": attributes["sku"],
                "type": attributes["type"],
            }
        elif item_type == "contact-informations":
            additional_data["contact_information"][item_id] = attributes

        elif item_type == "shipments":
            additional_data["shipments"][item_id] = {
                "tracking": relationships["shipment_trackings"]["data"],
                "items": relationships["shipment_items"]["data"],
                "contact_info": relationships["contact_information"]["data"]
                and relationships["contact_information"]["data"]["id"],
                "attributes": attributes,
                "packages": relationships["packages"]["data"],
                "shipping_method": (
                    relationships["shipping_method"]["data"]["id"]
                    if relationships["shipping_method"]["data"]
                    else None
                ),
            }
        # shipment items give us nothing but store anyway
        elif item_type == "shipment-items":
            additional_data["shipment_items"][item_id] = {
                **attributes,
                "order_item_id": relationships["order_item"]["data"]["id"],
            }
        elif item_type == "shipment-trackings":
            additional_data["shipment_trackings"][item_id] = attributes
        elif item_type == "shipping-methods":
            additional_data["shipping_methods"][item_id] = {
                "attributes": attributes,
                "carrier_id": relationships["shipping_carrier"]["data"]["id"],
            }
        elif item_type == "shipping-carriers":
            additional_data["shipping_carriers"][item_id] = (
                attributes["name"] or None
            )
        elif item_type == "shipping-boxes":
            additional_data["shipping_boxes"][item_id] = attributes
        elif item_type == "packages":
            additional_data["packages"][item_id] = {
                "package_order_items": relationships["package_order_items"]["data"],
                "shipping_box_id": relationships["shipping_box"]["data"]["id"],
                **attributes,
            }
        elif item_type == "package-order-items":
            additional_data["package_order_items"][item_id] = {
                **attributes,
                "order_item_id": relationships["order_item"]["data"]["id"],
                "lot_id": (
                    relationships["lot"]["data"]["id"]
                    if relationships["lot"]["data"]
                    else None
                ),
                "location_id": (
                    relationships["location"]["data"]["id"]
                    if relationships["location"]["data"]
                    else None
                ),
            }
        elif item_type == "lots":
            additional_data["lots"][item_id] = attributes
        elif item_type == "locations":
            additional_data["locations"][item_id] = {
                "warehouse_id": relationships["warehouse"]["data"]["id"]
            }
    return additional_data

def format_order(
    self,
    order,
    additional_data,
    merge_data={},
):
    order_id = order["id"]
    attributes = order["attributes"]
    relationships = order["relationships"]
    warehouse_customer_id = relationships["customer"]["data"]["id"]
    created_date = format_date(attributes["created_at"])
    updated_date = format_date(attributes["updated_at"])
    reference_id = str(attributes["external_id"] or order_id)
    order_number = attributes["number"] or reference_id
    raw_status = attributes["status_text"]
    if raw_status.lower() == "fulfilled":
        status = "fulfilled"
    elif raw_status.lower() == "cancelled":
        status = "cancelled"
    elif raw_status.lower() == "pending":
        hold_keys = ["fraud_hold", "address_hold", "payment_hold", "operator_hold"]
        held_reasons = [hk for hk in hold_keys if attributes[hk]]
        if held_reasons:
            status = "exception"
            raw_status = ", ".join(held_reasons)
        else:
            status = "open"
    else:
        status = "other"

    channel_relationship_id = None
    channel_data = relationships["order_channel"]["data"]
    channel = channel_object = None
    if channel_data:
        channel_relationship_id = channel_data["id"]
        # i think the id is the relationship, not the actual channel
        channel = additional_data["channels"][channel_relationship_id]
        channel_object = {
            "channel_id": f"{channel}_{warehouse_customer_id}",
            "channel_name": channel,
        }

    shipping_carrier_data = self.get_shipping_carrier_data(
        relationships, attributes, additional_data
    )
    shipping_method_id = shipping_carrier_data.get("shipping_method_id")
    shipping_method_name = shipping_carrier_data.get("shipping_method_name")
    carrier_id = shipping_carrier_data.get("carrier_id")
    carrier_name = shipping_carrier_data.get("carrier_name")

    invoice_currency_code = "USD"
    total_price = attributes["total"]
    total_tax = attributes["tax"]
    total_discount = attributes["discount"]
    total_shipping = attributes["shipping"]
    # packiyo sends no contact on an order cancelled at creation (SO399534)
    ship_to_info = {
        "name": None,
        "company_name": None,
        "address": None,
        "address2": None,
        "city": None,
        "state": None,
        "zip": None,
        "country": None,
        "phone": None,
        "email": None,
    }
    shipping_contact_data = relationships["shipping_contact_information"]["data"]
    if shipping_contact_data:
        ship_to_info = additional_data["contact_information"][
            shipping_contact_data["id"]
        ]
    ship_to_address = {
        "full_name": ship_to_info["name"],
        "company": ship_to_info["company_name"],
        "address1": ship_to_info["address"],
        "address2": ship_to_info["address2"],
        "address3": IntegrationNotImplemented,
        "city": ship_to_info["city"],
        "state": ship_to_info["state"],
        "postal_code": ship_to_info["zip"],
        "country": ship_to_info["country"],
        "phone_number": ship_to_info["phone"],
        "email_address": ship_to_info["email"],
    }
    line_items = {}
    all_picked = {}
    order_line_item_ids = set()
    for item in relationships["order_items"]["data"]:
        line_item = additional_data["order_items"].get(item["id"])
        if not line_item:
            logger.info(
                f"Order item {item['id']} not found in additional data for order: {order_id}"
            )
            continue
        order_line_item_ids.add(item["id"])
        product_id = line_item["product_id"]
        sku = additional_data["products"][product_id]["sku"]
        product_type = additional_data["products"][product_id]["type"]
        # Kit components are already included as order items, so remove top level kits to avoid double counting
        if product_type == "kit":
            continue
        shipped_quantity = line_item["quantity_shipped"]
        quantity = line_item["quantity"]
        unit_price = line_item["price"]
        item_picked = shipped_quantity == quantity
        if sku in line_items:
            merged_line = line_items[sku]
            merged_quantity = merged_line["quantity"] + quantity
            # same sku on several order items: average the price so price * quantity still adds up
            if merged_line["unit_price"] is None or unit_price is None:
                merged_line["unit_price"] = None
            elif merged_quantity:
                merged_line["unit_price"] = (
                    merged_line["unit_price"] * merged_line["quantity"]
                    + unit_price * quantity
                ) / merged_quantity
            merged_line["quantity"] = merged_quantity
            if not item_picked:
                all_picked[sku] = False
        else:
            line_items[sku] = {
                "product_id": product_id,
                "sku": sku,
                "quantity": quantity,
                # packiyo prices each item per unit, including negative prices that offset shipping
                "unit_price": unit_price,
                "discount_amount": IntegrationNotImplemented,
            }
            all_picked[sku] = item_picked
        backordered_quantity = line_item["quantity_backordered"]
        if (
            backordered_quantity
            and attributes["allow_partial"] == 0
            and status not in ["cancelled", "fulfilled"]
        ):
            status = "backordered"

    line_items = list(line_items.values())
    order_picked = all(all_picked.values()) and line_items
    if order_picked and status in ["open", "other"]:
        status = "picked"
    shipments = []  # get from included

    for shipment in relationships["shipments"]["data"]:
        shipment_id = shipment["id"]
        additional_ship_info = additional_data["shipments"][shipment_id]
        ship_attributes = additional_ship_info["attributes"]
        shipment_cost = ship_attributes.get("cost")
        raw_shipment_status = ship_attributes["status_text"]
        shipment_status = "open"
        if raw_shipment_status.lower() == "voided":
            shipment_status = "cancelled"
        elif raw_shipment_status.lower() == "valid":
            shipment_status = "shipped"

        shipment_date = format_date(ship_attributes["created_at"])
        if shipment_date and shipment_date < "2024-09-01T00:00:00Z":
            # packiyo shipments before sept 2024 have bugs and are unreliable
            continue
        trackings = additional_ship_info["tracking"]
        tracking_info = []  # list to maintain order
        for t in trackings:
            tracking = additional_data["shipment_trackings"][t["id"]]
            if tracking["type"] != "shipping":
                continue
            tracking_info.append(tracking)

        packages = []
        avg_shipping_cost = (
            float(shipment_cost) / len(additional_ship_info["packages"])
            if shipment_cost and len(additional_ship_info["packages"]) > 0
            else None
        )
        shipment_warehouse_id = None
        shipment_shipping_method_id = additional_ship_info["shipping_method"]
        # TODO
        shipment_carrier_id = shipment_carrier_name = None
        shipment_shipping_method_name = None
        if shipment_shipping_method_id:
            method = additional_data["shipping_methods"][
                shipment_shipping_method_id
            ]
            shipment_shipping_method_name = method["attributes"]["name"]
            shipment_carrier_id = method["carrier_id"]
            shipment_carrier_name = additional_data["shipping_carriers"][
                shipment_carrier_id
            ]

        shipment_packages = additional_ship_info["packages"]
        use_single_tracking_info = len(tracking_info) != len(shipment_packages)
        for index, shipment_package in enumerate(shipment_packages):
            package_id = shipment_package["id"]
            package = additional_data["packages"][package_id]
            package_line_items = {}
            package_order_items = package["package_order_items"]
            package_shipping_box_id = package["shipping_box_id"]
            shipping_box = additional_data["shipping_boxes"][
                package_shipping_box_id
            ]
            package_name = shipping_box["name"]
            for package_order_item in package_order_items:
                package_order_item_id = package_order_item["id"]
                package_order_item_data = additional_data["package_order_items"][
                    package_order_item_id
                ]
                order_item_id = package_order_item_data["order_item_id"]
                if order_item_id not in order_line_item_ids:
                    continue
                product_id = additional_data["order_items"][order_item_id][
                    "product_id"
                ]
                product = additional_data["products"][product_id]
                lot_id = package_order_item_data["lot_id"]
                expiration_date = None
                if lot_id:
                    expiration_date = format_date(
                        additional_data["lots"][lot_id]["expiration_date"]
                    )
                    if expiration_date and expiration_date.startswith("-"):
                        expiration_date = None
                if not shipment_warehouse_id:
                    location_id = package_order_item_data["location_id"]
                    if location_id:
                        location = additional_data["locations"][location_id]
                        shipment_warehouse_id = location["warehouse_id"]
                if shipment_date and shipment_date > "2024-07-01T00:00:00Z":
                    # manual handling for old packiyo packages bug
                    if (
                        product["type"] == "kit"
                        and product_id in self.kit_components
                    ):
                        components = self.kit_components[product_id]
                        for component in components:
                            component_inv_id = component["inventory_item_id"]
                            key = (component_inv_id, product_id)
                            if key not in package_line_items:
                                package_line_items[key] = {
                                    "inventory_item_id": component_inv_id,
                                    "sku": component["sku"],
                                    "quantity": component["unit_quantity"],
                                    "lot_id": lot_id,
                                    "expiration_date": expiration_date,
                                    "parent_product_id": product_id,
                                }
                            else:
                                package_line_items[key]["quantity"] += component[
                                    "unit_quantity"
                                ]
                    else:
                        key = (product_id, None)
                        if key not in package_line_items:
                            package_line_items[key] = {
                                "inventory_item_id": product_id,
                                "sku": product["sku"],
                                "quantity": package_order_item_data["quantity"],
                                "lot_id": lot_id,
                                "expiration_date": expiration_date,
                                "parent_product_id": None,
                            }
                        else:
                            package_line_items[key]["quantity"] += (
                                package_order_item_data["quantity"]
                            )
            package_line_items = list(package_line_items.values())
            package_measurements = {
                "length": package["length"],
                "width": package["width"],
                "height": package["height"],
                "weight": package["weight"],
                "weight_unit": self.customer_units[warehouse_customer_id].get(
                    "weight_unit", "lb"
                ),
                "unit": self.customer_units[warehouse_customer_id].get(
                    "dimensions_unit", "in"
                ),
            }
            weight_unit = self.customer_units[warehouse_customer_id].get(
                "weight_unit", "lb"
            )
            if weight_unit == "g":
                package_measurements["weight"] = convert_weight_units(
                    float(package_measurements["weight"]), "g", "kg"
                )
                package_measurements["weight_unit"] = "kg"
            package_tracking_info = (
                (
                    tracking_info[0]
                    if use_single_tracking_info
                    else tracking_info[index]
                )
                if tracking_info
                else {}
            )
            package = {
                "package_id": package_id,
                "package_name": package_name,
                "tracking_number": package_tracking_info.get("tracking_number"),
                "tracking_url": (
                    package_tracking_info.get("tracking_url") or ""
                ).strip()
                or None,
                "shipping_method_id": shipment_shipping_method_id,
                "shipping_method_name": shipment_shipping_method_name,
                "carrier_id": shipment_carrier_id,
                "carrier_name": shipment_carrier_name,
                "scac": IntegrationNotImplemented,
                "bill_of_lading": IntegrationNotImplemented,
                "sscc": IntegrationNotImplemented,
                "pro_number": IntegrationNotImplemented,
                "shipping_cost": avg_shipping_cost,
                "measurements": package_measurements,
                "line_items": package_line_items,
            }
            packages.append(package)

        shipment_line_items = {}
        for package in packages:
            for line_item in package["line_items"]:
                inventory_item_id = line_item["inventory_item_id"]
                parent_product_id = line_item["parent_product_id"]
                key = (inventory_item_id, parent_product_id)
                if key not in shipment_line_items:
                    shipment_line_items[key] = {
                        "inventory_item_id": inventory_item_id,
                        "parent_product_id": parent_product_id,
                        "quantity": line_item["quantity"],
                        "sku": line_item["sku"],
                    }
                else:
                    shipment_line_items[key]["quantity"] += line_item["quantity"]
        shipment = {
            "shipment_id": shipment_id,
            "warehouse_id": shipment_warehouse_id
            or self.single_warehouse_id  # use default warehouse if not set
            or "unknown",  # TODO hack to get something in here until darius adds warehouse id to shipments
            "raw_status": raw_shipment_status,
            "status": shipment_status,
            "shipped_date": shipment_date,
            "line_items": list(shipment_line_items.values()),
            "ship_to_address": ship_to_address,
            "ship_from_address": IntegrationNotImplemented,
            "packages": packages,
        }
        shipments.append(shipment)
    if any(
        [shipment["status"] == "shipped" for shipment in shipments]
    ) and status in [
        "open",
        "backordered",
        "other",
    ]:
        status = "partially_fulfilled"
    tags = []
    order_tags = attributes["tags"]  # comma separated string
    if order_tags:
        tags = order_tags.split(",")
        [tag.strip() for tag in tags]

