def get_integration_secret(self, body):
    return {"token": body["token"], "tenant_name": body["tenant_name"]}

def validate_integration_secret(self):
    path = "users/me"
    self.packiyo_request(path)

def me(self):
    path = "users/me"
    return self.packiyo_request(path)

def safe_me(self):
    return self.me()

def safe_integration_secret_keys(self):
    return ["tenant_name", "customer_id"]

def base_url(self):
    return f"https://{self.integration_secret['tenant_name']}.packiyo.com/api/v1"

def packiyo_request(self, path, method="GET", empty_response=False, **kwargs):
    url = f"{self.base_url()}/{path}"
    headers = {
        "Authorization": f"Bearer {self.integration_secret['token']}",
    }
    if method in ["POST", "PUT", "PATCH"]:
        headers["Content-Type"] = "application/vnd.api+json"
        headers["Accept"] = "application/vnd.api+json"
    else:
        headers["Content-Type"] = "application/json"
    session = get_request_session()
    try:
        response = session.request(method, url, headers=headers, **kwargs)
    except SSLError:
        raise self.create_invalid_credentials_exception()

    if not response.ok:
        if response.status_code in [401, 503]:
            raise self.create_invalid_credentials_exception()
        else:
            raise PokedexException(
                response.text, response.status_code, origin="integration"
            )
    if empty_response:
        return {}
    try:
        js = response.json()
    except (json.JSONDecodeError, ValueError):
        # Packiyo returns HTML when token is invalid
        raise self.create_invalid_credentials_exception()
    return js

